<?php
declare(strict_types=1);
require_once __DIR__.'/../modules/auth.php';require_once __DIR__.'/../modules/affiliate-community.php';require_once __DIR__.'/../modules/affiliate-groups.php';require_once __DIR__.'/../modules/affiliates.php';require_login();start_app_session();if(empty($_SESSION['events_csrf']))$_SESSION['events_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['events_csrf'];$error='';$flash='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}try{if(!app_user_can('events','create'))throw new DomainException('Sem permissão para agendar eventos.');affiliate_event_save($_POST,(string)current_user()['id']);$flash='Reunião agendada e publicada para o público escolhido.';}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Não foi possível salvar o evento.';error_log('[AFFILIEY] events: '.$e->getMessage());}}
$events=affiliate_event_list();$affiliates=affiliate_read_all();$groups=affiliate_group_list();function ev_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
